#!/usr/bin/env python3
"""Regenerate the versioned dataset crosswalk from source-verified findings."""
import csv
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
HEAD=['dataset_id','publication_or_repository','doi_or_url','record_count_and_scope','spatial_unit_and_accuracy','temporal_precision_and_fields','licenses_and_access','owner_contact_route','decision_relevance_and_unresolved']
REPO='https://github.com/theoneste2060/rwanda_landslide_inventory/tree/main/datasets_v2/repo_readonly/v2'
ROWS=[
['D01','User-linked Rwanda inventory v2 events.csv',REPO,'88 curated event records spanning 1963–2026','Reported event/episode rows; source locations mixed: 77 point rows, none states accuracy ≤1 km; 28 point accuracy values blank, other stated point accuracies 5–25 km; 494 polygon rows are mixed-hazard with no per-feature landslide-vs-flood field in the extract.','66 day-precision rows, but no matched daily/subdaily rainfall series or non-event time panel; conservative filter 25 event rows → 21 distinct dates; no measured terrain/rainfall predictors.','Upstream LICENSE.md says no single open license applies to the compiled v2 package; source terms are mixed/incompletely documented. No blanket redistribution permission is asserted; see input/LICENSE.md and input/sources.csv.','https://github.com/theoneste2060/rwanda_landslide_inventory','Candidate temporal case list only; not ready for ML. Same-date rows and storm groups require primary-source adjudication; 21 dates are an upper bound, not 21 confirmed independent trigger events.'],
['D02','User-linked Rwanda inventory v2 sites.csv',REPO,'1,071 geometry rows: 77 points; 494 polygons; 494 polygon centroids; 6 AOI centers','Point rows are reporting locations/approximations, not surveyed scar coordinates; centroids are derived; six AOI centers are not event locations.','No consistent event-time measure on these geometry rows; sites link to event IDs but do not supply matched rainfall.','Upstream LICENSE.md says no single open license applies to the compiled v2 package; source terms are mixed/incompletely documented. No blanket redistribution permission is asserted; see input/LICENSE.md and input/sources.csv.','https://github.com/theoneste2060/rwanda_landslide_inventory','Do not use derived/mixed-hazard geometries as 30 m initiation labels without feature-class review and corrected geometry.'],
['D03','REMA 2022 regional shallow-landslide training inventory (as described in report)','https://www.rema.gov.rw/fileadmin/user_upload/REMA/Publications/Reports/Report_2_-_Landslide_Risks_Assessment_and_Mitigation_Report_3.pdf','2,544 recent shallow landslide observations from western Rwanda over 2000–2019','One manually assigned initiation point/pixel per mapped landslide; impact zones excluded from susceptibility response. The exact 2,544-point machine-readable layer and its regional-boundary crosswalk were not found in the repository/report PDF.','Report describes initiation as bounded between satellite-image dates, but exact image-date pairs are not exposed in the PDF or the public 7,944-point file. No day-level event date was used for rainfall thresholds.','Report is public; no report reuse license was identified. Exact GIS inputs/version and point layer require request. The open Zenodo file below is a related updated release, not yet demonstrated identical.','REMA: https://www.rema.gov.rw/home; authors: arthur.depicker@kuleuven.be; olivier.dewitte@africamuseum.be.','Suitable basis for regional static susceptibility as originally modeled, if exact points/raster stack/background recipe are obtained; 2,544 mapped pixels are not 2,544 independent day-level trigger cases.'],
['D04','Public regional point inventory / Zenodo 5027004','https://doi.org/10.5281/zenodo.5027004','7,944 point geometries; North Tanganyika–Kivu region, including parts of DRC/Rwanda/Burundi','Shapefile POINT; EPSG:4326; bbox 28.00679–29.99884°E, −4.53182–−1.00905°; article states one manually defined initiation point per shallow landslide. No polygons in archive.','Raw DBF fields: ID, area, dep_area, Year; no image-date pair or type field. Year has 1,259 negative signed values, 6,685 positive values, no nulls, and 34 distinct signed values. The sign coding is undocumented; do not treat raw Year values as calendar years until author confirmation. Field units/meanings of area and dep_area also require confirmation.','Public Zenodo record and shapefile licensed CC BY 4.0; ZIP is 244,446 bytes, MD5 matches Zenodo API. Downloaded into this package; attribution required.','Authors: arthur.depicker@kuleuven.be; olivier.dewitte@africamuseum.be.','Open regional candidate for static susceptibility after confirming attribute semantics and exact 2,544 subset; not usable for rainfall-threshold training until Year/date coding and image brackets are resolved.'],
['D05','REMA local four-subcatchment multi-temporal inventory (Report 2 Step 1)','https://www.rema.gov.rw/fileadmin/user_upload/REMA/Publications/Reports/Report_2_-_Landslide_Risks_Assessment_and_Mitigation_Report_3.pdf','22 old deep-seated landslides and 5 recent deep-seated flow slides/earthflows','Manually assigned polygons in four small catchments; old-mass boundaries are uncertain; polygon/map deliverables mentioned in report but no separate feature file found in report/repository.','Recent means between two imagery dates; old age undetermined; not a daily event catalogue. Report found no shallow landslides in the four catchments in imagery but explicitly says non-detection does not prove none occurred.','Public report; spatial deliverables/feature files and reuse terms not located; request from REMA/authors.','REMA and report authors: https://www.rema.gov.rw/home; olivier.dewitte@africamuseum.be.','Use as a distinct ground-deformation/old-mass susceptibility layer; not as shallow-rainfall model labels.'],
['D06','Monsieurs et al. 2018 LIWEAR regional inventory','https://doi.org/10.1007/s10346-018-1008-y','143 location/date-known events from 1968–2016 per publisher abstract','Event points/locations; source-published accuracy not fully established for machine-readable file in this review.','Known date and location in publisher description; exact date/location field schema not obtained.','Publisher lists supplementary material as authorized-user access; no open event layer or separate data license verified. No access control bypassed.','Publisher/article author route; Ghent Dept Geography https://www.geography.ugent.be/contact-us; RMCA counterpart olivier.dewitte@africamuseum.be.','Potential historical event source; ask for permission, file schema, reporting-selection bias and geolocation certainty.'],
['D07','Monsieurs et al. 2019 western EARS event/threshold inventory','https://doi.org/10.5194/nhess-19-775-2019','174 events from 2001–2018; 29 mining events excluded, leaving 143 for threshold calibration','Article reports mean location accuracy 6.7 km; row-level event geometry not identified in accessed article/supplement route.','Daily dates are described; article uses rainfall records and susceptibility; period 2001–2018.','NHESS article is CC BY 4.0 and public supplement route exists; no separate row-level event-location file was verified.','Authors through NHESS article route; Ghent/RMCA contact routes above.','Strong method precedent, not a ready-to-use event layer until supplementary data and exact reuse conditions are confirmed.'],
['D08','Uwihirwe et al. (2020) Rwanda trigger-threshold study','https://doi.org/10.1007/s10346-020-01457-9','59 rainfall-event conditions with one or more landslides and 60 non-landslide rainy-day conditions identified from Rwanda 2006–2018 catalogue','Study-level event locations/representative conditions; not an exact geospatial layer delivered in the report reviewed here.','The study reports 9,353 MPRE from 34,438 rainy days in its broader rainfall/non-landslide panel; event/day pairing and antecedent rainfall windows are described.','Publisher article page opened; access to individual event/panel data not confirmed in this review.','Article author/publisher route.','Local reference threshold method; fitted true/false alarm rates are study-specific and not independent prospective performance.'],
['D09','Riveros et al. (2022) Rwanda hydro-meteorological threshold study','https://doi.org/10.5194/nhess-22-3641-2022','55 accurately dated landslides from 2007–2019; 32 inside modeled catchments','Reported spatial accuracy varies 5–25 km; study uses buffers for precipitation/soil-moisture matching.','Accurately dated events over 2007–2019, but not all are exact scar coordinates; authors say the inventory likely misses less damaging events.','Open NHESS article; separate raw event-row release was not verified from the inspected article/data route.','Article author/publisher route.','Potential validation/threshold comparator; not complete national data and not equivalent to the user’s 88-row compilation.'],
['D10','Nature Sustainability figure source data (not an occurrence layer)','https://doi.org/10.6084/m9.figshare.14838825.v1','One Excel workbook for figures 3–5 of historical risk analysis','Tabular/figure source data, not individual point/polygon geometries.','Historical aggregations/figures; not suitable for day-level triggering.','Figshare CC BY 4.0 verified by API.','https://figshare.com/articles/dataset/Figure_data_used_in_the_manuscript_entitled_Historical_dynamics_of_landslide_risk_from_population_and_forest_cover_changes_in_the_Kivu_Rift_/14838825.','Useful for reproducing figures, not susceptibility labels or operational thresholds.'],
['D11','4TU.ResearchData Rwanda landslide event workbook (included as an upstream raw-source snapshot)','https://github.com/theoneste2060/rwanda_landslide_inventory/tree/main/datasets_v2/repo_readonly/v2/raw_sources/4tu_rwanda_inventory.xlsx','70 source rows; README describes the landslide inventory as 2006–2021; worksheet is 71 rows × 35 columns including the header.','Point-like `Shape` values plus `latitude`/`longitude`; `location_accuracy` varies from 5 km/10 km/25 km to Unknown and other values. Not surveyed scar coordinates or initiation points.','Fields include `event_date`, `event_time`, `latitude`, `longitude`, `location_accuracy`, `landslide_category`, `landslide_trigger`, `landslide_size`, impacts and source IDs/links. No imagery-date brackets, source/impact polygons, or confirmed initiation point field.','Upstream raw-source README identifies the 4TU dataset record as CC0; retained workbook README identifies J. Uwihirwe as author and the source context.','J. Uwihirwe, J.Uwihirwe@tudelft.nl; record access route is preserved in input/raw_sources/4tu_rwanda_inventory_readme.txt.','A source-record/event catalogue that feeds the 88-row compilation; 70 source rows are not 70 independent storm episodes. Reconcile dates, coordinates and duplicate source records before threshold work.'],
['D12','Deijns et al. (2022) SAR-timed geomorphic-hazard inventory, Rwanda component / Zenodo 7198322','https://doi.org/10.5281/zenodo.7198322','494 Rwanda polygon features in the public file; Zenodo record describes four regional event inventories with around 2,500 manually mapped landslides and flash floods in total.','POLYGON shapefile, original CRS WGS 84 / UTM zone 35S; fields: id, Area, LandUsemaj, Aspectmean, Slopemean, ASC_MASKma, DSC_MASKma, Aspect.','No date, image-date pair, initiation point, or explicit per-feature landslide/flash-flood class field in the inspected Rwanda DBF. The dataset combines landslides and flash floods.','Zenodo record/API says CC BY 4.0; public. The source archive and Zenodo metadata snapshot are included under input/raw_sources; attribution required.','Dataset authors via https://doi.org/10.5281/zenodo.7198322 and associated NHESS article.','Do not promote polygons to confirmed landslide scar labels or use as rainfall-event cases without feature-level hazard classification and dates.'],
['D13','Depicker et al. Geomorphology 6,446-landslide catalogue (source registry aliases 2020a and 2020b)','https://doi.org/10.1016/j.geomorph.2019.106886','6,446 landslides described in one article; 29% deep-seated and 198 larger than 5 ha. The two supplied 2020a/2020b registry labels resolve to this same DOI.','Exact downloadable geometry type, coordinate accuracy and per-record spatial fields were not verified.','Exact temporal fields, per-record date precision and image-pair metadata were not verified.','Publisher/institutional article text opened; no separately downloadable primary catalogue or dataset license verified. Do not transfer the CC BY 4.0 license of the later Zenodo 7,944-point dataset to this catalogue.','Arthur Depicker: arthur.depicker@kuleuven.be; Olivier Dewitte: olivier.dewitte@africamuseum.be.','Keep distinct from the open 7,944-point 2021 update and REMA 2,544-point subset until the authors provide a version crosswalk; do not treat duplicate 2020a/2020b citations as separate datasets.'],
]
with (ROOT/'inventory_dataset_crosswalk.csv').open('w',encoding='utf-8-sig',newline='') as f:
    w=csv.writer(f);w.writerow(HEAD);w.writerows(ROWS)
with (ROOT/'inventory_dataset_crosswalk.csv').open(encoding='utf-8-sig',newline='') as f:
    parsed=list(csv.reader(f));assert all(len(r)==len(HEAD) for r in parsed);assert len(parsed)-1==len(ROWS)
print(f'Wrote and validated {len(ROWS)} crosswalk rows.')
